pub enum PCFFitPolicyOffset {}

/// Fit policy: how long an arc a fit uses, how that is validated, and what a
/// fit refuses.
#[derive(Copy, Clone, PartialEq)]
pub struct PCFFitPolicy<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for PCFFitPolicy<'a> {
    type Inner = PCFFitPolicy<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> PCFFitPolicy<'a> {
    pub const VT_DEFAULT_SPAN_HOURS: ::flatbuffers::VOffsetT = 4;
    pub const VT_MINIMUM_SPAN_HOURS: ::flatbuffers::VOffsetT = 6;
    pub const VT_MAXIMUM_SPAN_HOURS: ::flatbuffers::VOffsetT = 8;
    pub const VT_CANDIDATE_SPANS_HOURS: ::flatbuffers::VOffsetT = 10;
    pub const VT_TAIL_HOURS: ::flatbuffers::VOffsetT = 12;
    pub const VT_EXTENSION_MARGIN: ::flatbuffers::VOffsetT = 14;
    pub const VT_HOLDOUT_HOURS: ::flatbuffers::VOffsetT = 16;
    pub const VT_HAS_HOLDOUT_HOURS: ::flatbuffers::VOffsetT = 18;
    pub const VT_ECCENTRICITY_THRESHOLD: ::flatbuffers::VOffsetT = 20;
    pub const VT_ECCENTRIC_DEFAULT_SPAN_HOURS: ::flatbuffers::VOffsetT = 22;
    pub const VT_ECCENTRIC_EXTENSION_MARGIN: ::flatbuffers::VOffsetT = 24;
    pub const VT_ECCENTRIC_MAXIMUM_PERIOD_HOURS: ::flatbuffers::VOffsetT = 26;
    pub const VT_IMPLAUSIBLE_RMS_KM: ::flatbuffers::VOffsetT = 28;
    pub const VT_DRAG_PRIOR: ::flatbuffers::VOffsetT = 30;
    pub const VT_SRP_PRIOR: ::flatbuffers::VOffsetT = 32;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        PCFFitPolicy { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args PCFFitPolicyArgs<'args>
    ) -> ::flatbuffers::WIPOffset<PCFFitPolicy<'bldr>> {
        let mut builder = PCFFitPolicyBuilder::new(_fbb);
        builder.add_IMPLAUSIBLE_RMS_KM(args.IMPLAUSIBLE_RMS_KM);
        builder.add_ECCENTRIC_MAXIMUM_PERIOD_HOURS(args.ECCENTRIC_MAXIMUM_PERIOD_HOURS);
        builder.add_ECCENTRIC_EXTENSION_MARGIN(args.ECCENTRIC_EXTENSION_MARGIN);
        builder.add_ECCENTRIC_DEFAULT_SPAN_HOURS(args.ECCENTRIC_DEFAULT_SPAN_HOURS);
        builder.add_ECCENTRICITY_THRESHOLD(args.ECCENTRICITY_THRESHOLD);
        builder.add_HOLDOUT_HOURS(args.HOLDOUT_HOURS);
        builder.add_EXTENSION_MARGIN(args.EXTENSION_MARGIN);
        builder.add_TAIL_HOURS(args.TAIL_HOURS);
        builder.add_MAXIMUM_SPAN_HOURS(args.MAXIMUM_SPAN_HOURS);
        builder.add_MINIMUM_SPAN_HOURS(args.MINIMUM_SPAN_HOURS);
        builder.add_DEFAULT_SPAN_HOURS(args.DEFAULT_SPAN_HOURS);
        if let Some(x) = args.SRP_PRIOR { builder.add_SRP_PRIOR(x); }
        if let Some(x) = args.DRAG_PRIOR { builder.add_DRAG_PRIOR(x); }
        if let Some(x) = args.CANDIDATE_SPANS_HOURS { builder.add_CANDIDATE_SPANS_HOURS(x); }
        builder.add_HAS_HOLDOUT_HOURS(args.HAS_HOLDOUT_HOURS);
        builder.finish()
    }

    pub fn unpack(&self) -> PCFFitPolicyT {
        let DEFAULT_SPAN_HOURS = self.DEFAULT_SPAN_HOURS();
        let MINIMUM_SPAN_HOURS = self.MINIMUM_SPAN_HOURS();
        let MAXIMUM_SPAN_HOURS = self.MAXIMUM_SPAN_HOURS();
        let CANDIDATE_SPANS_HOURS = self.CANDIDATE_SPANS_HOURS().map(|x| {
            x.into_iter().collect()
        });
        let TAIL_HOURS = self.TAIL_HOURS();
        let EXTENSION_MARGIN = self.EXTENSION_MARGIN();
        let HOLDOUT_HOURS = self.HOLDOUT_HOURS();
        let HAS_HOLDOUT_HOURS = self.HAS_HOLDOUT_HOURS();
        let ECCENTRICITY_THRESHOLD = self.ECCENTRICITY_THRESHOLD();
        let ECCENTRIC_DEFAULT_SPAN_HOURS = self.ECCENTRIC_DEFAULT_SPAN_HOURS();
        let ECCENTRIC_EXTENSION_MARGIN = self.ECCENTRIC_EXTENSION_MARGIN();
        let ECCENTRIC_MAXIMUM_PERIOD_HOURS = self.ECCENTRIC_MAXIMUM_PERIOD_HOURS();
        let IMPLAUSIBLE_RMS_KM = self.IMPLAUSIBLE_RMS_KM();
        let DRAG_PRIOR = self.DRAG_PRIOR().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let SRP_PRIOR = self.SRP_PRIOR().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        PCFFitPolicyT {
            DEFAULT_SPAN_HOURS,
            MINIMUM_SPAN_HOURS,
            MAXIMUM_SPAN_HOURS,
            CANDIDATE_SPANS_HOURS,
            TAIL_HOURS,
            EXTENSION_MARGIN,
            HOLDOUT_HOURS,
            HAS_HOLDOUT_HOURS,
            ECCENTRICITY_THRESHOLD,
            ECCENTRIC_DEFAULT_SPAN_HOURS,
            ECCENTRIC_EXTENSION_MARGIN,
            ECCENTRIC_MAXIMUM_PERIOD_HOURS,
            IMPLAUSIBLE_RMS_KM,
            DRAG_PRIOR,
            SRP_PRIOR,
        }
    }

    /// Fit span used when the span rule is not run, hours. Default 48.
    #[inline]
    pub fn DEFAULT_SPAN_HOURS(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_DEFAULT_SPAN_HOURS, Some(48.0)).unwrap()}
    }

    /// Shortest span a fit may take, hours. Default 24.
    #[inline]
    pub fn MINIMUM_SPAN_HOURS(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_MINIMUM_SPAN_HOURS, Some(24.0)).unwrap()}
    }

    /// Longest span a fit may take, hours. Default 120.
    #[inline]
    pub fn MAXIMUM_SPAN_HOURS(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_MAXIMUM_SPAN_HOURS, Some(120.0)).unwrap()}
    }

    /// Spans the extension rule scores, ascending, hours, each within
    /// [MINIMUM_SPAN_HOURS, MAXIMUM_SPAN_HOURS]. Empty: 48, 72 and 120; with
    /// 24 in front when the eccentricity exceeds ECCENTRICITY_THRESHOLD.
    #[inline]
    pub fn CANDIDATE_SPANS_HOURS(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(PCFFitPolicy::VT_CANDIDATE_SPANS_HOURS, None)}
    }

    /// Validation tail: each candidate is fitted to the data before the latest
    /// TAIL_HOURS and scored on that tail, hours. Default 24.
    #[inline]
    pub fn TAIL_HOURS(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_TAIL_HOURS, Some(24.0)).unwrap()}
    }

    /// Extension rule: a longer candidate is taken only when its tail error is
    /// at most this fraction of the best shorter candidate's. Default 0.9.
    #[inline]
    pub fn EXTENSION_MARGIN(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_EXTENSION_MARGIN, Some(0.9)).unwrap()}
    }

    /// Hours held out at the end of the data and reported as error growth; the
    /// fit then ends HOLDOUT_HOURS before the data does. Absent, the data
    /// block's own useable stop time decides.
    #[inline]
    pub fn HOLDOUT_HOURS(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_HOLDOUT_HOURS, Some(0.0)).unwrap()}
    }

    /// True when HOLDOUT_HOURS carries a value; false means absent.
    #[inline]
    pub fn HAS_HOLDOUT_HOURS(&self) -> bool {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<bool>(PCFFitPolicy::VT_HAS_HOLDOUT_HOURS, Some(false)).unwrap()}
    }

    /// Eccentricity above which the eccentric-orbit rule applies. Default 0.5.
    #[inline]
    pub fn ECCENTRICITY_THRESHOLD(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_ECCENTRICITY_THRESHOLD, Some(0.5)).unwrap()}
    }

    /// Eccentric orbits: the default span, hours. Default 24.
    #[inline]
    pub fn ECCENTRIC_DEFAULT_SPAN_HOURS(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_ECCENTRIC_DEFAULT_SPAN_HOURS, Some(24.0)).unwrap()}
    }

    /// Eccentric orbits: EXTENSION_MARGIN. Default 0.7.
    #[inline]
    pub fn ECCENTRIC_EXTENSION_MARGIN(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_ECCENTRIC_EXTENSION_MARGIN, Some(0.7)).unwrap()}
    }

    /// Eccentric orbits: no candidate longer than this is tried once the orbital
    /// period passes it, hours. Default 36.
    #[inline]
    pub fn ECCENTRIC_MAXIMUM_PERIOD_HOURS(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_ECCENTRIC_MAXIMUM_PERIOD_HOURS, Some(36.0)).unwrap()}
    }

    /// A fit whose RMS passes this is refused as fit-implausible, km. Default
    /// 100.
    #[inline]
    pub fn IMPLAUSIBLE_RMS_KM(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(PCFFitPolicy::VT_IMPLAUSIBLE_RMS_KM, Some(100.0)).unwrap()}
    }

    /// Prior on B_eff, the signed drag area-to-mass ratio Cd*A/m, m2/kg. Absent
    /// or without sigma: mean 0; sigma 1.0 for SDNAP, 0.05 for SGP4XP.
    #[inline]
    pub fn DRAG_PRIOR(&self) -> Option<PCFGaussianPrior<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<PCFGaussianPrior>>(PCFFitPolicy::VT_DRAG_PRIOR, None)}
    }

    /// Prior on AGOM, the radiation-pressure area-to-mass ratio Cr*A/m, m2/kg.
    /// Absent or without sigma: mean 0, sigma 0.05.
    #[inline]
    pub fn SRP_PRIOR(&self) -> Option<PCFGaussianPrior<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<PCFGaussianPrior>>(PCFFitPolicy::VT_SRP_PRIOR, None)}
    }
}

impl ::flatbuffers::Verifiable for PCFFitPolicy<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<f64>("DEFAULT_SPAN_HOURS", Self::VT_DEFAULT_SPAN_HOURS, false)?
            .visit_field::<f64>("MINIMUM_SPAN_HOURS", Self::VT_MINIMUM_SPAN_HOURS, false)?
            .visit_field::<f64>("MAXIMUM_SPAN_HOURS", Self::VT_MAXIMUM_SPAN_HOURS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("CANDIDATE_SPANS_HOURS", Self::VT_CANDIDATE_SPANS_HOURS, false)?
            .visit_field::<f64>("TAIL_HOURS", Self::VT_TAIL_HOURS, false)?
            .visit_field::<f64>("EXTENSION_MARGIN", Self::VT_EXTENSION_MARGIN, false)?
            .visit_field::<f64>("HOLDOUT_HOURS", Self::VT_HOLDOUT_HOURS, false)?
            .visit_field::<bool>("HAS_HOLDOUT_HOURS", Self::VT_HAS_HOLDOUT_HOURS, false)?
            .visit_field::<f64>("ECCENTRICITY_THRESHOLD", Self::VT_ECCENTRICITY_THRESHOLD, false)?
            .visit_field::<f64>("ECCENTRIC_DEFAULT_SPAN_HOURS", Self::VT_ECCENTRIC_DEFAULT_SPAN_HOURS, false)?
            .visit_field::<f64>("ECCENTRIC_EXTENSION_MARGIN", Self::VT_ECCENTRIC_EXTENSION_MARGIN, false)?
            .visit_field::<f64>("ECCENTRIC_MAXIMUM_PERIOD_HOURS", Self::VT_ECCENTRIC_MAXIMUM_PERIOD_HOURS, false)?
            .visit_field::<f64>("IMPLAUSIBLE_RMS_KM", Self::VT_IMPLAUSIBLE_RMS_KM, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<PCFGaussianPrior>>("DRAG_PRIOR", Self::VT_DRAG_PRIOR, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<PCFGaussianPrior>>("SRP_PRIOR", Self::VT_SRP_PRIOR, false)?
            .finish();
        Ok(())
    }
}

