pub struct PCFIntegratorSettingsBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> PCFIntegratorSettingsBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_ALGORITHM(&mut self, ALGORITHM: pcfIntegratorAlgorithm) {
        self.fbb_.push_slot::<pcfIntegratorAlgorithm>(PCFIntegratorSettings::VT_ALGORITHM, ALGORITHM, pcfIntegratorAlgorithm::UNSPECIFIED);
    }

    #[inline]
    pub fn add_INITIAL_STEP_SECONDS(&mut self, INITIAL_STEP_SECONDS: f64) {
        self.fbb_.push_slot::<f64>(PCFIntegratorSettings::VT_INITIAL_STEP_SECONDS, INITIAL_STEP_SECONDS, 60.0);
    }

    #[inline]
    pub fn add_MINIMUM_STEP_SECONDS(&mut self, MINIMUM_STEP_SECONDS: f64) {
        self.fbb_.push_slot::<f64>(PCFIntegratorSettings::VT_MINIMUM_STEP_SECONDS, MINIMUM_STEP_SECONDS, 1.0);
    }

    #[inline]
    pub fn add_MAXIMUM_STEP_SECONDS(&mut self, MAXIMUM_STEP_SECONDS: f64) {
        self.fbb_.push_slot::<f64>(PCFIntegratorSettings::VT_MAXIMUM_STEP_SECONDS, MAXIMUM_STEP_SECONDS, 3600.0);
    }

    #[inline]
    pub fn add_ABSOLUTE_TOLERANCES(&mut self, ABSOLUTE_TOLERANCES: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(PCFIntegratorSettings::VT_ABSOLUTE_TOLERANCES, ABSOLUTE_TOLERANCES);
    }

    #[inline]
    pub fn add_RELATIVE_TOLERANCE(&mut self, RELATIVE_TOLERANCE: f64) {
        self.fbb_.push_slot::<f64>(PCFIntegratorSettings::VT_RELATIVE_TOLERANCE, RELATIVE_TOLERANCE, 1e-12);
    }

    #[inline]
    pub fn add_MAXIMUM_STEPS(&mut self, MAXIMUM_STEPS: u32) {
        self.fbb_.push_slot::<u32>(PCFIntegratorSettings::VT_MAXIMUM_STEPS, MAXIMUM_STEPS, 100000);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> PCFIntegratorSettingsBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        PCFIntegratorSettingsBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<PCFIntegratorSettings<'a>> {
        let o = self.fbb_.end_table(self.start_);
        self.fbb_.required(o, PCFIntegratorSettings::VT_ABSOLUTE_TOLERANCES,"ABSOLUTE_TOLERANCES");
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

